import random

def maker_pnl(n, alpha, delta, s, seed):
    """Average profit per trade, in pence a share.
    You buy at V - s and sell at V + s.
    The value is V + delta or V - delta."""
    rng = random.Random(seed)
    total = 0.0
    for _ in range(n):
        high = rng.random() < 0.5      # value is V + delta
        informed = rng.random() < alpha
        if informed:
            buys = high                # they know the value
        else:
            buys = rng.random() < 0.5  # noise: a coin flip
        d = delta if high else -delta  # value minus V
        if buys:
            total += s - d             # you sold at V + s
        else:
            total += s + d             # you bought at V - s
    return total / n
